import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

// Dashboard.jsx
// React functional component (default export)
// - Uses Bootstrap (assumes you include bootstrap CSS in index.html)
// - Fetches /api/dashboard (expects JSON as confirmed)
// - Redirects to /login on unauthorized

export default function Dashboard() {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [user, setUser] = useState(null);
    const [stats, setStats] = useState({});

    useEffect(() => {
        const token = localStorage.getItem("jwt_token");
        if (!token) {
            navigate("/login");
            return;
        }

        async function fetchData() {
            try {
                const res = await fetch("/api/dashboard/-summary", {
                    method: "GET",
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`,
                    },
                });

                if (res.status === 401 || res.status === 403) {
                    // token expired or unauthorized
                    localStorage.removeItem("jwt_token");
                    navigate("/login");
                    return;
                }

                if (!res.ok) {
                    const body = await res.json().catch(() => ({}));
                    throw new Error(body.message || "Failed to load dashboard");
                }

                const data = await res.json();

                // expected structure (confirmed): { user: { fullname, email, primary_role }, stats: { ... } }
                setUser(data.user || null);
                setStats(data.stats || {});
                setLoading(false);
            } catch (err) {
                setError(err.message);
                setLoading(false);
            }
        }

        fetchData();
    }, [navigate]);

    if (loading) {
        return (
            <div className="container mt-5">
                <div className="text-center">Loading dashboard…</div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="container mt-5">
                <div className="alert alert-danger">{error}</div>
            </div>
        );
    }

    const isAdmin = user && user.primary_role === "admin";

    // helper to render a summary card
    const Card = ({ bgClass = "bg-light", title, value, description, btnText, btnHref }) => (
        <div className="col-md-4 mb-3">
            <div className={`card text-white dashboard-card ${bgClass}`}>
                <div className="card-body text-center">
                    <h5 className="card-title">{title}</h5>
                    <h2>{value ?? 0}</h2>
                    <p className="card-text">{description}</p>
                    {btnText && (
                        <button
                            className={`btn ${bgClass === "bg-light" ? "btn-outline-dark" : "btn-light"} btn-sm"`}
                            onClick={() => (btnHref ? (window.location.href = btnHref) : null)}
                        >
                            {btnText}
                        </button>
                    )}
                </div>
            </div>
        </div>
    );

    return (
        <div className="container mt-5 pt-4">
            <div className="text-center mt-4">
                <h2>Welcome, {user.fullname}</h2>
                <p className="text-muted">{user.email}</p>
                <hr />
            </div>

            {/* User-level summary cards */}
            <div className="row text-center mt-4">
                <Card
                    bgClass="bg-success"
                    title="📝 Active Consents"
                    value={stats.active_consents}
                    description="Consents Granted"
                    btnText="View My Consents"
                    btnHref="/myconsents"
                />

                <Card
                    bgClass="bg-warning text-dark"
                    title="📨 Grievances"
                    value={stats.grievances_count}
                    description="Filed by You"
                    btnText="My Grievances"
                    btnHref="/mygrievances"
                />

                <Card
                    bgClass="bg-info"
                    title="🔔 Notifications"
                    value={stats.unread_notifications}
                    description="Unread Notifications"
                    btnText="View Notifications"
                    btnHref="/notifications"
                />
            </div>

            {/* Admin-specific summary and controls (kept alongside existing controls) */}
            {isAdmin ? (
                <>
                    <div className="text-center mt-4">
                        <h3 className="mb-3 text-primary">Admin Dashboard</h3>
                        <p>Manage users, companies, and consent data.</p>
                    </div>

                    <div className="row text-center mt-4">
                        <div className="col-md-3 mb-3">
                            <div className="card bg-primary text-white dashboard-card">
                                <div className="card-body">
                                    <h5 className="card-title">👥 Users</h5>
                                    <h2>{stats.total_users ?? 0}</h2>
                                    <a href="/showallusers" className="btn btn-light btn-sm mt-2">Manage Users</a>
                                </div>
                            </div>
                        </div>

                        <div className="col-md-3 mb-3">
                            <div className="card bg-success text-white dashboard-card">
                                <div className="card-body">
                                    <h5 className="card-title">📝 Consents</h5>
                                    <h2>{stats.total_consents ?? 0}</h2>
                                    <a href="/showallconsents" className="btn btn-light btn-sm mt-2">View Consents</a>
                                </div>
                            </div>
                        </div>

                        <div className="col-md-3 mb-3">
                            <div className="card bg-warning text-dark dashboard-card">
                                <div className="card-body">
                                    <h5 className="card-title">💬 Feedbacks</h5>
                                    <h2>{stats.total_feedbacks ?? 0}</h2>
                                    <a href="/showallfeedbacks" className="btn btn-dark btn-sm mt-2">View Feedbacks</a>
                                </div>
                            </div>
                        </div>

                        <div className="col-md-3 mb-3">
                            <div className="card bg-danger text-white dashboard-card">
                                <div className="card-body">
                                    <h5 className="card-title">⚖️ Grievances</h5>
                                    <h2>{stats.total_grievances ?? 0}</h2>
                                    <a href="/admin/grievances" className="btn btn-light btn-sm mt-2">View Grievances</a>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="text-center mt-4">
                        <div className="d-flex flex-wrap justify-content-center gap-3 mt-4">
                            <a href="/showallusers" className="btn btn-outline-primary">View All Users</a>
                            <a href="/showallconsents" className="btn btn-outline-danger">View All Consents</a>
                            <a href="/showallfeedbacks" className="btn btn-outline-success">View Feedbacks</a>
                            <a href="/admin/fiduciaries" className="btn btn-outline-info">Manage Fiduciaries</a>
                            <a href="/admin/roles" className="btn btn-outline-warning">Manage Roles</a>
                            <a href="/admin/purposes" className="btn btn-outline-secondary">Manage Purposes</a>
                            <a href="/admin/mailtemplates" className="btn btn-outline-dark">Mail Templates</a>
                            <a href="/admin/grievances" className="btn btn-outline-danger">Manage Grievances</a>
                        </div>
                    </div>
                </>
            ) : (
                <div className="text-center mt-4">
                    <h3 className="mb-3 text-success">{user.primary_role?.charAt(0).toUpperCase() + user.primary_role?.slice(1)} Dashboard</h3>
                    <p>Welcome to your personalized DPCMS dashboard.</p>

                    <div className="d-flex flex-wrap justify-content-center gap-3 mt-4">
                        <a href="/consent/status" className="btn btn-primary">Manage Consent</a>
                        <a href="/myconsents" className="btn btn-success me-2">My Consents</a>
                        <a href="/mygrievances" className="btn btn-warning">My Grievances</a>
                        <a href="/notifications" className="btn btn-info me-2">My Notifications</a>
                    </div>
                </div>
            )}
        </div>
    );
}
